{
    [ComVisible(true)]
    [ClassInterface(ClassInterfaceType.AutoDual)]
    [AutoGuid]
    [BsonIgnoreExtraElements]
    [JsonSchemaExtensionData("example",
  @"{
          ""CodigoRevenda"": ""1"",
          ""NomeRazaoSocial"": ""Microsum Tecnologia da Informação Ltda"",
          ""Pessoa"": ""JURÍDICA"",
