			  ""PaisDescricao"": ""Brasil""
		  },
          ""CPFCNPJ"": ""05.462.662/0001-05"",
          ""IE"": ""10.358.086-7"",
          ""IM"": ""1926829"",
          ""logotipoB64"": ""data:image/jpeg;base64,"",
          ""DFE"": {
            ""Ativo"": false,
            ""configBD"": {
              ""host"": ""192.168.1.202"",
