            }
          },
          ""PAY"":{
            ""Ativo"": false,
            ""configBD"": {
              ""host"": ""192.168.1.202"",
              ""porta"": ""27017""
            }
          },
         ""HUB"":{
            ""Ativo"": false,
            ""LimiteCanais"": 2,
            ""configBD"": {
              ""host"": ""SERVER\\SQL2019PDI"",
              ""porta"": ""1433""
            }
          },
          ""TAX"":{
            ""Ativo"":  false,
            ""configBD"": {
              ""host"": ""192.168.1.202"",
              ""porta"": ""27017""
            }
        },
          ""EFD"":{
            ""Ativo"":  false,
            ""configBD"": {
              ""host"": ""SERVER\\SQL2019PDI"",
              ""porta"": ""1433""
            }
        }
    }")]
    public class ClienteVM
    {
        public string Id { get; set; }

        /// <summary>
        /// Código sequencial do cliente
        /// </summary>
        public string Codigo { get; set; }

        public string CodigoRevenda { get; set; }

        public string NomeRazaoSocial { get; set; }

        public EnderecoVM Endereco { get; set; } = new EnderecoVM();

        public ContatosVM Contatos { get; set; } = new ContatosVM();

        [JsonSchemaExtensionData("example", "01.078.133/0001-43")]
        public string CPFCNPJ { get; set; }

        public string IE { get; set; }

        public string IM { get; set; }

        public EPessoa Pessoa { get; set; }

        public string ApelidoFantasia { get; set; }

        public EContribuinte Contribuinte { get; set; }

        public string DI { get; set; }

        [ComVisible(false)]

        [System.Xml.Serialization.XmlIgnoreAttribute()]
        public ICollection<ClienteTokenVM> Tokens { get; set; } = new List<ClienteTokenVM>();

        [ComVisible(false)]
        [System.Xml.Serialization.XmlIgnoreAttribute()]
        public ICollection<ClienteWebHookVM> WebHooks { get; set; } = new List<ClienteWebHookVM>();

        //[JsonIgnore]
        [System.Xml.Serialization.XmlIgnoreAttribute()]
        public ClienteCertificadoVM Certificado { get; set; } = new ClienteCertificadoVM();

        // [JsonIgnore]
        [JsonSchemaExtensionData("example", "data:image/jpeg;base64,")]
        public string LogotipoB64 { get; set; }

        public DFeVM DFE { get; set; } = new DFeVM();

        public PayVM PAY { get; set; } = new PayVM();

        public TaxVM TAX { get; set; } = new TaxVM();

        public HubVM HUB { get; set; } = new HubVM();

        public EfdVM EFD { get; set; } = new EfdVM();

        public string NomeRevenda { get; set; }

        public string ApelidoRevenda { get; set; }

        public string GetFirstToken()
        {
            var token = Tokens.Where(t => t.Revogacao > DateTime.Today).FirstOrDefault();
            if (token == null)
            {
                return "";

            }
            return token.Token;
        }

        [ComVisible(false)]
        public void SetListToken(ICollection<ClienteTokenVM> tokenVMs)
        {
            this.Tokens = tokenVMs;
        }

        public string GetCpfOrCnpj()
        {
            if (!string.IsNullOrEmpty(CPFCNPJ))
            {
                return CPFCNPJ.SomenteNumeros();
            }
            else
            {
                return "";
            }
        }

        public bool IsCodigoRevendaValido()
        {
            if (string.IsNullOrEmpty(CodigoRevenda) || string.IsNullOrWhiteSpace(CodigoRevenda))
            {
                return false;
            }
            else
            {
                return true;
            }
        }

        public ClienteVMPack ToClientVMPack()
        {
            ClienteVMPack clienteVMPack = new ClienteVMPack()
            {
                Codigo = Codigo,
                CodigoRevenda = CodigoRevenda,
                NomeRazaoSocial = NomeRazaoSocial,
                Endereco = Endereco.ToEnderecoVMPack(),
                Contatos = Contatos.ToContatosVMPack(),
                CPFCNPJ = CPFCNPJ,
                IE = IE,
                IM = IM,
                Pessoa = Pessoa,
                ApelidoFantasia = ApelidoFantasia,
                Contribuinte = Contribuinte,
                DI = DI,
                LogotipoB64 = LogotipoB64,
                Tokens = Tokens?.ToListTokenVMPack(),
                WebHooks = WebHooks?.ToListWebHookVMPack(),
                Certificado = Certificado?.ToClienteCertificadoVMPack(),
                DFE = DFE?.ToDFeVMPack(),
                PAY = PAY?.ToPayVMPack(),
                TAX = TAX?.ToTaxVMPack(),
                HUB = HUB?.ToHubVMPack(),
                EFD = EFD?.ToEfdVMPack()
            };

            return clienteVMPack;
        }
    }
}